//! Cloudflare Workers + D1 + R2 + KV + AI + Queue codegen
//! Produces files compatible with the user's wrangler.toml

use crate::error::AxResult;
use std::path::Path;

pub fn generate(ax_file: &Path, out_dir: &Path) -> AxResult<()> {
    std::fs::create_dir_all(out_dir)?;

    // 1. Main worker
    let worker_js = r#"/**
 * AXBridge Ultra – Cloudflare Worker
 * Generated by axc (AXCode Ultra Compiler)
 * Compatible with:
 *   name = "al2100beta"
 *   D1 = AL_DB
 *   KV = AL_KV
 *   R2 = AL_BUCKET
 *   Queue = AL_QUEUE
 *   AI = AI
 */

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const path = url.pathname;

    // CORS
    if (request.method === "OPTIONS") {
      return new Response(null, { headers: corsHeaders() });
    }

    try {
      // Auth & admin guard
      if (path.startsWith("/admin")) {
        const email = request.headers.get("X-User-Email");
        if (email !== "axelgadomski@icloud.com") {
          return json({ error: "Admin access denied" }, 403);
        }
      }

      // Routes
      if (path === "/api/health") {
        return json({ status: "ok", version: "1.2.0-ultra" });
      }

      if (path === "/api/translate" && request.method === "POST") {
        return handleTranslate(request, env);
      }

      if (path === "/api/music/generate" && request.method === "POST") {
        return handleMusicGenerate(request, env);
      }

      if (path.startsWith("/api/tiktak")) {
        return handleTikTak(request, env, path);
      }

      if (path.startsWith("/api/messages")) {
        return handleMessages(request, env, path);
      }

      if (path.startsWith("/api/upload")) {
        return handleUpload(request, env);
      }

      // Static assets
      if (env.ASSETS) {
        return env.ASSETS.fetch(request);
      }

      return json({ error: "Not found" }, 404);
    } catch (err) {
      console.error(err);
      return json({ error: "Internal error", detail: String(err) }, 500);
    }
  },

  // Queue consumer for heavy music generation
  async queue(batch, env) {
    for (const msg of batch.messages) {
      const { prompt, mood, provider, userId } = msg.body;
      // Call Suno / Puter / HF here, store result in R2 + D1
      console.log("Generating music", prompt, mood, provider);
      msg.ack();
    }
  }
};

function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET,POST,PUT,DELETE,OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization, X-User-Email",
  };
}

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json", ...corsHeaders() },
  });
}

async function handleTranslate(request, env) {
  const body = await request.json();
  const { text, targetLang = "en" } = body;

  // Prefer AI binding or external provider (DeepL / Puter)
  // Fallback simple placeholder
  const translated = targetLang === "en" ? `[EN] ${text}` : `[PL] ${text}`;

  // Cache in KV
  const cacheKey = `tr:${targetLang}:${hash(text)}`;
  await env.AL_KV.put(cacheKey, translated, { expirationTtl: 86400 * 7 });

  return json({ original: text, translated, lang: targetLang });
}

async function handleMusicGenerate(request, env) {
  const body = await request.json();
  // Push to queue for async generation
  await env.AL_QUEUE.send({
    prompt: body.prompt,
    mood: body.mood || "happy",
    provider: body.provider || "suno",
    userId: body.userId,
  });
  return json({ status: "queued", message: "Music generation started" });
}

async function handleTikTak(request, env, path) {
  if (request.method === "GET") {
    const { results } = await env.AL_DB.prepare(
      "SELECT * FROM tiktak_posts ORDER BY created_at DESC LIMIT 50"
    ).all();
    return json({ posts: results || [] });
  }
  if (request.method === "POST") {
    const body = await request.json();
    await env.AL_DB.prepare(
      "INSERT INTO tiktak_posts (id, author_id, caption, media_url, media_type, is_funny, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)"
    ).bind(
      crypto.randomUUID(),
      body.authorId,
      body.caption,
      body.mediaUrl,
      body.mediaType,
      body.isFunny ? 1 : 0,
      new Date().toISOString()
    ).run();
    return json({ status: "ok" });
  }
  return json({ error: "Method not allowed" }, 405);
}

async function handleMessages(request, env, path) {
  // E2EE: server only stores ciphertext
  if (request.method === "POST") {
    const body = await request.json();
    await env.AL_DB.prepare(
      "INSERT INTO messages (id, conversation_id, sender_id, ciphertext, nonce, type, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)"
    ).bind(
      body.id,
      body.conversationId,
      body.senderId,
      body.ciphertext,
      body.nonce,
      body.type,
      new Date().toISOString()
    ).run();
    return json({ status: "ok" });
  }
  return json({ error: "Not implemented" }, 501);
}

async function handleUpload(request, env) {
  // Upload avatar / music / tiktak media to R2
  const form = await request.formData();
  const file = form.get("file");
  if (!file) return json({ error: "No file" }, 400);

  const key = `uploads/${crypto.randomUUID()}-${file.name}`;
  await env.AL_BUCKET.put(key, file.stream(), {
    httpMetadata: { contentType: file.type },
  });
  return json({ url: `r2://${key}`, key });
}

function hash(str) {
  // simple non-crypto hash for cache keys
  let h = 0;
  for (let i = 0; i < str.length; i++) h = (Math.imul(31, h) + str.charCodeAt(i)) | 0;
  return h.toString(16);
}
"#;

    std::fs::write(out_dir.join("worker.js"), worker_js)?;

    // 2. D1 schema
    let schema = r#"-- AXBridge Ultra – D1 schema
-- Generated by axc

CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  public_id TEXT UNIQUE,
  email TEXT,
  display_name TEXT NOT NULL,
  avatar_url TEXT,
  public_key TEXT,
  persona TEXT DEFAULT 'general',
  preferred_lang TEXT DEFAULT 'pl',
  is_admin INTEGER DEFAULT 0,
  created_at TEXT NOT NULL,
  last_seen TEXT
);

CREATE TABLE IF NOT EXISTS conversations (
  id TEXT PRIMARY KEY,
  type TEXT DEFAULT 'direct',
  title TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS conversation_participants (
  conversation_id TEXT,
  user_id TEXT,
  PRIMARY KEY (conversation_id, user_id)
);

CREATE TABLE IF NOT EXISTS messages (
  id TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL,
  sender_id TEXT NOT NULL,
  type TEXT NOT NULL,
  ciphertext BLOB NOT NULL,
  nonce BLOB,
  created_at TEXT NOT NULL,
  status TEXT DEFAULT 'sent'
);

CREATE TABLE IF NOT EXISTS tiktak_posts (
  id TEXT PRIMARY KEY,
  author_id TEXT NOT NULL,
  caption TEXT,
  media_url TEXT,
  media_type TEXT,
  is_funny INTEGER DEFAULT 1,
  likes INTEGER DEFAULT 0,
  comments INTEGER DEFAULT 0,
  created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS communities (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  cover_url TEXT,
  owner_id TEXT,
  member_count INTEGER DEFAULT 0,
  is_private INTEGER DEFAULT 0,
  created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS music_cache (
  id TEXT PRIMARY KEY,
  title TEXT,
  provider TEXT,
  prompt TEXT,
  mood TEXT,
  r2_key TEXT,
  duration_ms INTEGER,
  created_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_messages_conv ON messages(conversation_id, created_at);
CREATE INDEX IF NOT EXISTS idx_tiktak_created ON tiktak_posts(created_at DESC);
"#;

    std::fs::write(out_dir.join("schema.sql"), schema)?;

    // 3. wrangler snippet reminder
    let readme = r#"# Generated Cloudflare Worker for AXBridge Ultra

Place this folder next to your existing wrangler.toml or merge the bindings.

Required bindings (already in your config):
- AL_DB      → D1
- AL_KV      → KV
- AL_BUCKET  → R2
- AL_QUEUE   → Queue
- AI         → Workers AI
- ASSETS     → static assets

Admin email hard-coded: axelgadomski@icloud.com

Commands:
  npx wrangler d1 execute AL_DB --file=./schema.sql
  npx wrangler deploy
"#;
    std::fs::write(out_dir.join("README.md"), readme)?;

    println!("✓ Cloudflare Worker generated in {}", out_dir.display());
    println!("  - worker.js");
    println!("  - schema.sql");
    println!("  - README.md");
    Ok(())
}
